function shop(){const q=new URLSearchParams(location.hash.split('?')[1]||'');return `<div class="page-head"><span class="eyebrow">THE DOCNOVA COLLECTION</span><h1>Considered essentials.</h1><p>Tailored scrubs for women and men, cut for movement and made to see you through every shift — alongside the medical essentials you rely on at home.</p></div><div class="shop-layout"><aside class="filters"><h3>Refine your edit</h3>${[['category','Category',['All','Tops','Pants','Sets','Medical Devices','Jackets','Underscrubs','Accessories']],['fit','Fit',['All','Women','Men']],['size','Size',['All',...sizes]],['color','Colour',['All',...Object.keys(colors)]],['price','Price',['All','Under £40','£40–£60','Over £60']],['fabric','Fabric',['All','Four-way stretch']],['collection','Collection',['All','Scrubs','Core','Studio','Medical Essentials']]].map(([id,label,values])=>`<div><label for="filter-${id}">${label}</label><select id="filter-${id}" onchange="page=1;filterProducts()">${values.map(v=>`<option ${q.get(id)===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<button class="text-link" style="margin-top:20px" onclick="document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);page=1;filterProducts()">Clear filters</button></aside><div><div class="shop-top"><span id="result-count"></span><select id="sort" aria-label="Sort products" onchange="page=1;filterProducts()"><option>Featured</option><option>Newest</option><option>Best-selling</option><option>Price: low to high</option><option>Price: high to low</option></select></div><div id="results" class="grid shop-grid"></div><div id="pagination" class="pagination"></div></div></div>`}
function filterProducts(){let result=products.filter(p=>['category','fit','color','fabric','collection'].every(k=>$('#filter-'+k).value==='All'||(k==='collection'&&$('#filter-'+k).value==='Scrubs'?!p.device:p[k]===$('#filter-'+k).value)));if($('#filter-size').value!=='All')result=result.filter(p=>!p.device);const price=$('#filter-price').value;if(price==='Under £40')result=result.filter(p=>p.price<40);if(price==='£40–£60')result=result.filter(p=>p.price>=40&&p.price<=60);if(price==='Over £60')result=result.filter(p=>p.price>60);const sort=$('#sort').value;if(sort.includes('low to high'))result.sort((a,b)=>a.price-b.price);if(sort.includes('high to low'))result.sort((a,b)=>b.price-a.price);if(sort==='Newest')result.reverse();if(sort==='Best-selling')result.sort((a,b)=>Number(b.badge==='BEST SELLER')-Number(a.badge==='BEST SELLER'));$('#result-count').textContent=result.length+' essentials';$('#results').innerHTML=result.length?result.slice((page-1)*9,page*9).map(card).join(''):`<div class="empty"><h2>Your next essential is on its way.</h2><p>There are no available pieces in this selection yet.</p><button class="btn" onclick="location.hash='/shop'">Explore current collection</button></div>`;$('#pagination').innerHTML=Array.from({length:Math.ceil(result.length/9)},(_,i)=>`<button aria-label="Page ${i+1}" aria-current="${page===i+1?'page':'false'}" onclick="page=${i+1};filterProducts();document.querySelector('.shop-top').scrollIntoView()">${i+1}</button>`).join('')}
function sizeControls(){return `<div class="choices">${sizes.map(s=>`<button data-size="${s}" onclick="selectSize('${s}',this)">${s}</button>`).join('')}</div><p id="size-error" class="fine" role="alert"></p>`}
function selectSize(s,el){selectedSize=s;el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',b===el)});const err=$('#size-error');if(err)err.textContent=''}
function quickView(id){selectedProduct=products.find(p=>p.id===id);if(selectedProduct.device){deviceQuickView(selectedProduct);return}selectedSize='';const p=selectedProduct;modal(`<img src="${imageOf(p)}" style="width:150px;height:190px;float:left;margin:0 25px 20px 0" alt="${p.name}"><span class="eyebrow">${p.fit} · ${p.color}</span><h2>${p.name}</h2><p>${money(p.price)}</p><div style="clear:both">${colourOptions(p,true)}<label>Choose your size</label>${sizeControls()}<button class="btn full" onclick="addSelected()">Add to bag — ${money(p.price)}</button><p><a class="text-link" href="#/product/${id}" onclick="closeModal()">View full details ↗</a></p>${matchingPiece(p)}</div>`)}
function addSelected(buy=false){if(!$('#modal').open){const id=location.hash.split('/')[2];selectedProduct=products.find(p=>p.id===id)||selectedProduct;selectedSize=document.querySelector('#app [data-size].selected')?.dataset.size||'';}if(selectedProduct?.device)selectedSize='Standard';if(!selectedSize){const e=$('#size-error');if(e){e.textContent='Please choose a size to continue.';e.scrollIntoView({block:'center',behavior:'smooth'})}return}addToCart(selectedProduct.id,selectedSize);closeModal();if(buy)location.hash='/checkout';else openCart()}
function addToCart(id,size){if(!products.some(p=>p.id===id)||(!sizes.includes(size)&&!(size==='Standard'&&products.find(p=>p.id===id)?.device)))throw Error('Choose a valid product and size');const item=cart.find(x=>x.id===id&&x.size===size);if(item)item.qty++;else cart.push({id,size,qty:1});persist();return {id,size,quantity:cart.find(x=>x.id===id&&x.size===size).qty}}
function cartItems(edit=true){return cart.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="cart-item"><img src="${imageOf(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.device?'Medical device':p.color+' / '+x.size} · ${money(p.price)}</p>${edit?`<div class="quantity"><button aria-label="Decrease quantity" onclick="changeQty(${i},-1)">−</button><span>${x.qty}</span><button aria-label="Increase quantity" onclick="changeQty(${i},1)">+</button><button style="border:0;width:auto;font-size:12px" onclick="removeItem(${i})">Remove</button></div>`:`<span>Quantity: ${x.qty}</span>`}</div></div>`}).join('')}
let appliedCoupon='',couponPercent=0,couponReward=false;try{const c=JSON.parse(localStorage.getItem('docnova-coupon')||'null');if(c&&c.code&&(c.percent_off||c.reward)){appliedCoupon=c.code;couponPercent=c.percent_off||0;couponReward=!!c.reward}}catch(e){if(localStorage.getItem('docnova-coupon')==='WELCOME10'){appliedCoupon='WELCOME10';couponPercent=10}}
var DELIVERY_OPTIONS={uk:{label:'UK delivery',note:'Tracked delivery in 3–5 working days. Free on orders of £70 or more.'},ie:{label:'Republic of Ireland delivery',note:'Tracked delivery in 5–8 working days.'},collect:{label:'Click & Collect',note:'Free. Collect from us in the Cambridge area — our team will contact you the same day to arrange a time.'}};
let deliveryMethod=(()=>{try{const d=localStorage.getItem('docnova-delivery');return DELIVERY_OPTIONS[d]?d:'uk'}catch(e){return 'uk'}})();
var FREE_UK_FROM=70;
function freeUK(){return Math.round((subtotal()-discountAmount())*100)>=FREE_UK_FROM*100}
function deliveryCost(m=deliveryMethod){return m==='ie'?9.95:m==='collect'?0:(freeUK()?0:4.95)}
function setDelivery(m){if(!DELIVERY_OPTIONS[m])return;deliveryMethod=m;try{localStorage.setItem('docnova-delivery',m)}catch(e){}document.querySelectorAll('.delivery-option').forEach(x=>x.classList.toggle('active',x.dataset.method===m));$('#delivery-line')&&($('#delivery-line').innerHTML=deliveryLine());$('#order-total')&&($('#order-total').textContent=money(orderTotal()))}
function deliveryLine(){const c=deliveryCost();return `<span>${DELIVERY_OPTIONS[deliveryMethod].label}</span><span>${c?money(c):'Free'}</span>`}
function deliveryChoices(){const opts=[['uk','UK delivery',freeUK()?'Free':money(4.95)],['ie','Republic of Ireland',money(9.95)],['collect','Click & Collect','Free']];return `<fieldset class="delivery-choices"><legend>How would you like to receive your order?</legend>${opts.map(([k,l,p])=>`<label class="delivery-option ${k===deliveryMethod?'active':''}" data-method="${k}"><input type="radio" name="delivery" value="${k}" ${k===deliveryMethod?'checked':''} onchange="setDelivery('${k}')"><span class="d-main"><b>${l}</b><small>${DELIVERY_OPTIONS[k].note}</small></span><span class="d-price">${p}</span></label>`).join('')}</fieldset>`}
function subtotal(){return cart.reduce((n,x)=>n+Math.round(products.find(p=>p.id===x.id).price*100)*x.qty,0)/100}
function changeQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function removeItem(i){cart.splice(i,1);persist();if(location.hash==='#/checkout')$('#app').innerHTML=checkout();openCart()}
function openCart(){modal(`<h2>Your bag <span style="font:16px Arial">(${cart.reduce((n,x)=>n+x.qty,0)})</span></h2>${cart.length?`<p class="fine">${freeUK()?'Your order qualifies for free UK delivery.':'Spend '+money(Math.round((FREE_UK_FROM-(subtotal()-discountAmount()))*100)/100)+' more for free UK delivery.'}</p>${cartItems()}<div class="cart-total"><span>Subtotal</span><span>${money(subtotal())}</span></div>${roundsCartLine()}<p class="fine">UK delivery £4.95 (free over £70) · Republic of Ireland £9.95 · Click & Collect free</p><button class="btn full" onclick="closeModal();location.hash='/checkout'">Continue to checkout ↗</button><p class="fine">Secure checkout by Stripe · Cards, Apple Pay, Google Pay &amp; more</p><button class="text-link" onclick="closeModal();location.hash='/shop'">Continue shopping</button>`:`<div class="empty"><p>Your everyday essentials are waiting.</p><button class="btn" onclick="closeModal();location.hash='/shop'">Explore scrubs</button></div>`}`,true)}
function productPage(id){const p=products.find(x=>x.id===id);if(!p)return '<div class="content"><h1>Product not found</h1><a href="#/shop">Return to collection</a></div>';selectedProduct=p;if(p.device){selectedSize='Standard';return devicePage(p)}selectedSize='';const gallery=photos[p.group].slice(0,6);return `<div class="pdp"><div><p class="fine"><a href="#/shop">Collection</a> / ${p.category} / ${p.name}</p><img id="main-photo" class="gallery-main" src="${imageOf(p)}" alt="${p.name} in ${p.color}. Click to enlarge." tabindex="0" role="button" onclick="zoomPhoto()" onkeydown="if(event.key==='Enter')zoomPhoto()"><div class="thumbs">${gallery.map((im,i)=>`<button aria-label="View photograph ${i+1}" onclick="document.querySelector('#main-photo').src='${im}'"><img src="${im}" alt="${p.name}, view ${i+1}"></button>`).join('')}</div><p class="fine">Styled as a complete look. ${p.category==='Sets'?'Includes one top (£44.99) and one trouser (£49.99). Combined price £94.98; no set discount.':'Includes '+p.category.toLowerCase()+' only; other items shown are styling.'}</p></div><div class="product-detail"><span class="eyebrow">THE ${p.collection.toUpperCase()} COLLECTION · ${p.fit.toUpperCase()}</span><h1>${p.name}</h1><p class="price">${money(p.price)} ${p.old?`<del>${money(p.old)}</del>`:''}</p><a class="fine text-link" href="#/reviews">★★★★★ Read our Google reviews</a><p style="margin-top:22px">A refined essential for your daily rotation. A clean silhouette, comfortable stretch and thoughtful details — so you can focus on what matters.</p>${colourOptions(p)}<div style="display:flex;justify-content:space-between"><label>Size</label><a class="text-link" href="#/size-guide">Size guide ↗</a></div>${sizeControls()}<p class="fine">A modern regular fit. Between sizes? Choose the larger size for a more relaxed feel.</p><details class="size-details"><summary>Size chart (cm)</summary>${productSizeCharts(p)}<p class="fine"><a class="text-link" href="#/size-guide">How to measure ↗</a></p></details><div class="mobile-add"><button class="btn" onclick="addSelected()">Add to bag — ${money(p.price)}</button><button class="btn outline" onclick="addSelected(true)">Buy now</button></div>${productRoundsLine(p)}<p class="fine">✓ Easy-care design &nbsp; ✓ Stretch comfort &nbsp; ✓ Professional fit</p>${matchingPiece(p)}${[['The details','A modern neckline, practical storage and an easy silhouette. Designed to feel comfortable through a busy day.'],['Fabric & care','A soft, breathable blend of polyester, rayon and spandex. Polyester keeps its shape and colour wash after wash, rayon adds a smooth, cool feel against the skin, and 7% spandex gives four-way stretch so you can bend, reach and lift with ease.'+'<ul class="care-list"><li><strong>Fabric:</strong> 72% polyester, 21% rayon, 7% spandex</li><li>Machine wash at 40°C, or hand wash</li><li>Do not bleach</li><li>Wash with similar colours, inside out, to keep colours rich</li><li>Suitable for drying — line dry or use a low tumble setting to protect the stretch</li></ul>'],['Delivery & returns','UK delivery is £4.95, or free on orders of £70 or more (3–5 working days). Delivery to the Republic of Ireland is £9.95 (5–8 working days). Or choose free Click & Collect and our team will contact you the same day to arrange collection in the Cambridge area. You’ll get an order number straight away and a tracking number once your order is on its way. Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price. Medical devices can be returned within 30 days if unopened and in their original sealed packaging. Return postage is paid by the customer unless the item is faulty or we sent the wrong item. Email info@docnova.co.uk with your order number to start a return. This does not affect your statutory rights.']].map(([h,t])=>`<details><summary>${h}</summary><div class="detail-body"><p>${t.replace('<ul','</p><ul').replace('</ul>','</ul><p>')}</p></div></details>`).join('')}</div></div><section class="section"><div class="section-heading"><h2>Complete your rotation.</h2><a class="text-link" href="#/shop">Shop all ↗</a></div><div class="grid">${products.filter(x=>x.id!==id&&x.fit===p.fit).slice(0,4).map(card).join('')}</div></section><section class="section" style="padding-top:0"><h2>You may also like.</h2><div class="grid">${products.filter(x=>x.id!==id&&x.fit!==p.fit).slice(0,4).map(card).join('')}</div></section>${reviews()}`}
function zoomPhoto(){const src=$('#main-photo').src;modal(`<img src="${src}" style="max-height:76vh;object-fit:contain" alt="Enlarged product photograph">`)}
function openSearch(){modal(`<h2>Find your everyday.</h2><input class="search-input" aria-label="Search products" placeholder="Try navy, sets, or women…" oninput="searchResults(this.value)" autofocus><div id="search-results"></div>`);searchResults('')}
function searchResults(q){const list=products.filter(p=>(p.name+' '+p.color+' '+p.category+' '+p.fit).toLowerCase().includes(q.toLowerCase())).slice(0,6);$('#search-results').innerHTML=list.length?list.map(p=>`<a class="search-result" href="#/product/${p.id}" onclick="closeModal()"><img src="${imageOf(p)}" alt=""><div>${p.name}<br><span class="fine">${p.color} · ${money(p.price)}</span></div></a>`).join(''):'<p>No pieces found. Try a colour or category.</p>'}
function menu(){modal(`<h2>Explore DocNova</h2><div class="mega"><a href="#/" onclick="closeModal()">Home</a>${['Tops','Pants','Sets','Medical Devices','Jackets','Underscrubs','Accessories'].map(c=>`<a href="#/shop?category=${c}" onclick="closeModal()">${c} ↗</a>`).join('')}<a href="#/rounds" onclick="closeModal()">DocNova Rounds ✦</a><a href="#/about" onclick="closeModal()">Our story</a><a href="#/size-guide" onclick="closeModal()">Size guide</a></div>`)}
function account(){modal(`<h2>Your DocNova space.</h2><p>Keep your favourites close and pick up where you left off.</p><p class="fine">Your bag and wishlist are saved on this device.</p><button class="btn" onclick="closeModal();location.hash='/wishlist'">View your wishlist</button>`)}
const faqs=[['How do I choose my size?','All men’s and women’s scrubs come in S, M, L, XL and 2XL, in a modern regular fit. Our <a class="text-link" href="#/size-guide">size guide</a> lists the garment measurements for every size. If you are between sizes, choose the larger size for a more relaxed feel. Email info@docnova.co.uk or message us on WhatsApp and we’ll help you choose.'],['What is included in a scrub set?','Each set includes one matching top and one pair of trousers. Individual tops and pants are sold separately, even when photographed as a complete outfit.'],['What are DocNova scrubs made from?','A premium blend of 72% polyester, 21% rayon and 7% spandex — durable and colour-fast, soft against the skin, with four-way stretch for comfort through a long shift.'],['How should I care for my scrubs?','Machine wash at 40°C or hand wash, with similar colours and inside out. Do not bleach. Line dry or tumble dry on a low setting to protect the stretch.'],['Where do you deliver?','We deliver across the United Kingdom and to the Republic of Ireland. UK delivery is £4.95, or free on orders of £70 or more (3–5 working days). Delivery to the Republic of Ireland is £9.95 (5–8 working days). Or choose free Click & Collect and our team will contact you the same day to arrange collection in the Cambridge area. You’ll get an order number straight away and a tracking number once your order is on its way.'],['Can I return an item?','Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price. Medical devices can be returned within 30 days if unopened and in their original sealed packaging. Return postage is paid by the customer unless the item is faulty or we sent the wrong item. Email info@docnova.co.uk with your order number to start a return. This does not affect your statutory rights.'],['How can I pay?','Checkout takes you to a secure Stripe payment page. Depending on your device you can pay by debit or credit card, Apple Pay, Google Pay, Link and other options shown on the checkout page. DocNova never sees or stores your card details.'],['How do I track my order?','After payment you receive an order number such as DN-260926-7K4QP. Enter it with the email you used at checkout on the <a class="text-link" href="#/track-order">Track your order</a> page to see its status and, once dispatched, the tracking number.']];
function sizeGuide(){return `<div class="content size-guide"><span class="eyebrow">SIZE & FIT</span><h1>Find your everyday fit.</h1><p>Every DocNova scrub comes in S, M, L, XL and 2XL, in a modern regular fit. The charts below show garment measurements in centimetres, taken with the garment laid flat and measured all the way round.</p><div class="fit-tabs" role="tablist"><button role="tab" class="active" aria-selected="true" onclick="fitTab('Women',this)">Women</button><button role="tab" aria-selected="false" onclick="fitTab('Men',this)">Men</button></div><div id="fit-Women" class="fit-panel">${sizeTable('Women','top','Women’s scrub top')}${sizeTable('Women','trousers','Women’s scrub trousers')}</div><div id="fit-Men" class="fit-panel" hidden>${sizeTable('Men','top','Men’s scrub top')}${sizeTable('Men','trousers','Men’s scrub trousers')}</div><h3 style="margin-top:44px">How to measure</h3><ul class="care-list"><li><strong>Chest:</strong> around the fullest part of your chest, under the arms.</li><li><strong>Waist:</strong> around your natural waist, the narrowest part of your torso.</li><li><strong>Hips:</strong> around the fullest part of your hips.</li><li><strong>Shoulder:</strong> across the back, from one shoulder point to the other.</li></ul><p>Keep the tape level and snug, without pulling it tight. Compare your measurements with the chart and allow a few centimetres for ease of movement. Between sizes? Choose the larger size for a more relaxed feel.</p><p>Still unsure? Email <a class="text-link" href="mailto:info@docnova.co.uk">info@docnova.co.uk</a> or message us on <a class="text-link" href="https://wa.me/353894484100?text=Hello%20DocNova" target="_blank" rel="noopener">WhatsApp</a> and we’ll help you choose.</p><a class="text-link" href="#/shop">Explore the collection ↗</a></div>`}
function fitTab(f,b){document.querySelectorAll('.fit-panel').forEach(x=>x.hidden=x.id!=='fit-'+f);document.querySelectorAll('.fit-tabs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b)})}
function checkout(){if(!cart.length)return `<div class="content"><h1>Your bag is waiting.</h1><p>Add an essential to begin your checkout.</p><a class="btn" href="#/shop">Shop scrubs</a></div>`;return `<div class="checkout"><div><span class="eyebrow">BAG / SECURE PAYMENT / CONFIRMATION</span><h1>A better shift awaits.</h1><h3>Delivery</h3>${deliveryChoices()}<p class="fine">You’ll add your delivery address — or, for Click & Collect, your phone number — on the secure payment page.</p><h3 style="margin-top:30px">Ways to pay</h3><div id="pay-methods" class="pay-methods">${payMethodsMarkup()}</div><p class="fine">The options that suit your device appear on the next page, for example Apple Pay on iPhone and Safari, or Google Pay on Android and Chrome.</p><div id="checkout-error" class="notice" role="alert" hidden></div><button id="pay-button" class="btn full" style="margin-top:25px" onclick="startCheckout()">Continue to secure payment ↗</button><p class="fine secure-note">Payments are processed securely by Stripe. DocNova never sees or stores your card details. You’ll receive an order number to track your order.</p></div><aside class="order-summary"><h2 style="font-size:30px">Your essentials</h2>${cartItems(false)}<div class="cart-total"><span>Subtotal</span><span>${money(subtotal())}</span></div><p id="delivery-line" class="delivery-line">${deliveryLine()}</p><div id="checkout-offer">${couponMarkup()}</div><div class="cart-total"><strong>Total</strong><strong id="order-total">${money(orderTotal())}</strong></div><div id="checkout-rounds">${roundsCartLine()}</div><p class="fine">Prices shown in GBP.</p><button class="text-link" onclick="openCart()">Edit bag</button></aside></div>`}
function route(){if($('#modal').open)closeModal();const route=(location.hash.slice(1)||'/').split('?')[0];let html='';if(route==='/')html=home();else if(route==='/shop')html=shop();else if(route.startsWith('/product/'))html=productPage(route.split('/')[2]);else if(route==='/wishlist')html=`<div class="page-head"><span class="eyebrow">YOUR PERSONAL EDIT</span><h1>Saved for your next shift.</h1></div><section class="section" style="padding-top:0"><div class="grid">${wishlist.length?products.filter(p=>wishlist.includes(p.id)).map(card).join(''):'<div class="empty"><p>Your wishlist is ready for your favourites.</p><a class="btn" href="#/shop">Explore the collection</a></div>'}</div></section>`;else if(route==='/about')html=`<section class="story"><img src="assets/9-0.webp" alt="Healthcare professional in DocNova green scrubs"><div class="story-copy"><span class="eyebrow">OUR STORY</span><h1>Made by healthcare professionals.<br><em>For healthcare professionals.</em></h1><p>DocNova was born on the hospital floor. As a family of healthcare professionals, we have seen first-hand how much a uniform shapes a long shift — and we set out to create scrubs that care for the people who care for everyone else.</p><a class="btn" href="#/shop">Explore the collection</a></div></section>
<section class="about-block about-intro"><div class="about-narrow"><span class="eyebrow">THREE YEARS IN THE MAKING</span><h2>No shortcuts. No compromise.</h2><p>For more than three years we have worked towards one goal: premium-quality scrubs and essential medical devices, offered at a fair and competitive price. We tested fabrics, refined patterns and questioned every seam until the result felt right on a twelve-hour shift — not just on a hanger.</p><p>The journey has demanded patience and hard work. At every stage there was a quicker, cheaper option — and at every stage we chose quality instead. Every DocNova piece is the result of that commitment: no compromise on design, materials, finish or service.</p></div>
<div class="about-stats"><div><strong>3+</strong><span>years in development</span></div><div><strong>S–2XL</strong><span>sizes for women and men</span></div><div><strong>4-way</strong><span>stretch fabric</span></div><div><strong>UK</strong><span>based, family-run</span></div></div></section>
<section class="about-block about-family"><div class="about-split"><img src="assets/4-2.webp" alt="Healthcare professional in DocNova green scrubs" loading="lazy"><div><span class="eyebrow">A FAMILY OF HEALTHCARE PROFESSIONALS</span><h2>We know the shift, because we work it.</h2><p>As a family of healthcare professionals, we understand what a long day really asks of you: hours on your feet, constant movement, changing wards and environments, and the need to look composed from the first handover to the last.</p><p>Every DocNova piece is designed around that reality — so you can stay comfortable, move freely and focus on what matters most: your patients. Because when patient safety comes first, your uniform should never get in the way.</p></div></div></section>
<section class="about-block"><div class="about-narrow center"><span class="eyebrow">WHAT GOES INTO EVERY PIECE</span><h2>Comfort and confidence, in balance.</h2><p>Professionalism, comfort and modern style — designed to work together, never traded against each other.</p></div>
<div class="about-pillars"><div><span class="num">01</span><h3>Four-way stretch</h3><p>A soft, premium blend of 72% polyester, 21% rayon and 7% spandex that bends, reaches and lifts with you through every task.</p></div><div><span class="num">02</span><h3>Easy to care for</h3><p>Wrinkle-resistant and quick to launder, so you look fresh at the start of every shift with minimal effort.</p></div><div><span class="num">03</span><h3>Tailored finish</h3><p>Precise stitching and considered tailoring give a clean, structured shape that holds up wash after wash.</p></div><div><span class="num">04</span><h3>Professional style</h3><p>A modern, polished silhouette that reflects the professional you are — on the ward, in clinic or on the road.</p></div></div></section>
<section class="about-block about-roles"><div class="about-split reverse"><img src="assets/10-0.webp" alt="Healthcare professional in DocNova black scrubs" loading="lazy"><div><span class="eyebrow">FOR EVERY ROLE IN CARE</span><h2>Our heroes, in every department.</h2><p>We make DocNova for the full line of healthcare professionals — from the medical student on their first placement to the consultant leading the team.</p><ul class="role-list"><li>Medical students</li><li>Doctors</li><li>Nurses</li><li>Paramedics</li><li>Healthcare assistants</li><li>Allied health professionals</li></ul><p>We value your dedication, your professionalism and the difference you make to our communities every single day. Designing for you is our way of saying thank you.</p></div></div></section>
<section class="about-block about-give"><div class="about-narrow center"><span class="eyebrow">GIVING BACK</span><h2>Care that reaches further.</h2><p>Healthcare is about community, and so is DocNova. We aim to give a share of our sales to welfare and charitable causes, directing support to where it is needed most. As we grow, so will our contribution.</p></div></section>
<section class="about-block"><div class="about-promise"><div><span class="eyebrow">OUR PROMISE</span><h2>Premium quality. Fair prices. Real service.</h2></div><div><p><strong>Quality without compromise.</strong> Every garment and device we offer has been chosen to meet the standard we would expect for ourselves.</p><p><strong>Competitive pricing.</strong> Premium shouldn’t mean out of reach — our prices are set to be fair to the people who need them most.</p><p><strong>Service that listens.</strong> Every order is handled with care, and every question is answered personally — by email or WhatsApp — because our customers are the heroes we built DocNova for.</p></div></div></section>
<section class="about-block about-feedback"><div class="about-narrow center"><span class="eyebrow">WE’RE LISTENING</span><h2>Help us get even better.</h2><p>Every day is a new opportunity to learn and improve. As a UK-based brand, we value your opinion above all — your reviews and feedback directly shape what we make next. Tell us what you love, and what we could do even better.</p><div class="about-actions"><a class="btn" href="https://search.google.com/local/writereview?placeid=ChIJsYc-YLZng2URQNsyBvUhTec" target="_blank" rel="noopener">Leave a Google review</a><a class="btn outline" href="https://wa.me/353894484100?text=Hello%20DocNova" target="_blank" rel="noopener">Message us on WhatsApp</a><a class="text-link" href="mailto:info@docnova.co.uk">info@docnova.co.uk</a></div><p class="fine" style="margin-top:26px">DocNova Ltd · Registered in England &amp; Wales No. 16502835 · Cambridge, UK</p></div></section>`;else if(route==='/size-guide')html=sizeGuide();else if(route==='/rounds')html=roundsPage();else if(route==='/reviews')html=reviews();else if(route==='/faq')html=`<div class="content"><span class="eyebrow">HERE TO HELP</span><h1>A few good answers.</h1>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;else if(route==='/checkout')html=checkout();else if(route==='/order-confirmed'||route==='/confirmation')html=orderConfirmedPage();else if(route==='/track-order')html=trackOrderPage();else{const texts={"shipping": ["Delivery & returns", "<h3>Delivery</h3><p>We deliver across the United Kingdom and to the Republic of Ireland, and offer Click & Collect in the Cambridge area.</p><div class=\"table-wrap\"><table class=\"spec-table\"><tr><th>United Kingdom</th><td>£4.95 · free on orders of £70 or more · 3–5 working days</td></tr><tr><th>Republic of Ireland</th><td>£9.95 · 5–8 working days</td></tr><tr><th>Click & Collect</th><td>Free · we’ll contact you the same day to arrange collection in the Cambridge area</td></tr></table></div><p>Prices are charged in pounds sterling; your bank may apply its own conversion for euro cards.</p><p>Orders are usually dispatched within 1–2 working days and arrive in 3–5 working days. You’ll receive an order number as soon as you pay, and a tracking number by email once your order is on its way. You can check progress any time on the <a class=\"text-link\" href=\"#/track-order\">Track your order</a> page.</p><h3>Returns</h3><p>Changed your mind? Unworn, unwashed scrubs with their tags attached can be returned within 30 days of delivery for a full refund of the item price.</p><p>For hygiene reasons, blood pressure monitors and thermometers can be returned only if unopened and in their original sealed packaging.</p><p>To start a return, email <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a> with your order number and the items you’re sending back. Return postage is paid by you unless the item is faulty or we sent the wrong item. We refund to your original payment method within 14 days of receiving your return.</p><h3>Faulty or wrong items</h3><p>If something arrives damaged, faulty or isn’t what you ordered, contact us within 30 days and we’ll put it right with a replacement or full refund, including postage.</p><p>These terms don’t affect your statutory rights under the Consumer Rights Act 2015 and the Consumer Contracts Regulations 2013.</p>"], "privacy": ["Privacy policy", "<p>DocNova Ltd (company no. 16502835, based in Cambridge, UK) is responsible for the personal data we collect through this website. Contact us at <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a> about anything in this notice.</p><h3>What we collect and why</h3><p><strong>Orders:</strong> your name, email address, phone number, delivery address and what you bought — to take payment, deliver your order, send order and tracking emails and handle returns (needed to perform our contract with you).</p><p><strong>Payments:</strong> handled by Stripe. We never see or store your full card details.</p><p><strong>Newsletter:</strong> if you sign up, your email address and the time you agreed — to send collection news and offers (with your consent). Every email has an unsubscribe link.</p><p><strong>Your bag and wishlist:</strong> saved in your own browser, not on our servers.</p><h3>Who we share it with</h3><p>Only the services that help us run the shop: Stripe (payments), our email provider (order and newsletter emails), our website host and the delivery carrier. If you choose to message us on WhatsApp, that conversation is handled by WhatsApp (Meta). We never sell your data.</p><h3>How long we keep it</h3><p>Order records are kept for six years for tax and accounting. Newsletter details are kept until you unsubscribe.</p><h3>Your rights</h3><p>You can ask for a copy of your data, or ask us to correct or delete it, by emailing <a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a>. If you are unhappy with how we handle your data you can complain to the Information Commissioner’s Office (ico.org.uk).</p><p>This website doesn’t use advertising or analytics cookies.</p>"], "terms": ["Terms of sale", "<p>These terms apply to orders placed on docnova.co.uk with DocNova Ltd, registered in England & Wales (company no. 16502835) and based in Cambridge, UK.</p><h3>Orders and prices</h3><p>Prices are shown in pounds sterling. Your order is accepted when payment is confirmed and you receive your order number. If we can’t fulfil an order — for example if an item is out of stock — we’ll tell you and refund you in full.</p><h3>Payment</h3><p>Payments are processed securely by Stripe. The payment methods available depend on your device and are shown at checkout.</p><h3>Delivery, cancellations and returns</h3><p>We deliver within the UK. You have the right to cancel within 14 days of receiving your order, and our 30-day returns policy gives you longer — see <a class=\"text-link\" href=\"#/shipping\">Delivery & returns</a>.</p><h3>Medical devices</h3><p>Our blood pressure monitors and thermometers are for home use. Always read the user manual supplied with your device. Readings are not a diagnosis — speak to your GP or pharmacist about your results, and call 999 or 111 in an emergency.</p><h3>Law</h3><p>These terms are governed by the laws of England and Wales. Nothing in them affects your statutory rights.</p>"], "contact": ["Let’s talk.", "<p>Questions about sizing, an order or our medical devices? We’re happy to help.</p><div class=\"contact-cards\"><div><span class=\"eyebrow\">EMAIL</span><p><a class=\"text-link\" href=\"mailto:info@docnova.co.uk\">info@docnova.co.uk</a></p></div><div><span class=\"eyebrow\">WHATSAPP</span><p><a class=\"text-link\" href=\"https://wa.me/353894484100?text=Hello%20DocNova\" target=\"_blank\" rel=\"noopener\">Message us on WhatsApp</a></p></div><div><span class=\"eyebrow\">HOURS</span><p>Every day, 8am – 8pm</p></div><div><span class=\"eyebrow\">BASED IN</span><p>Cambridge, UK</p></div><div><span class=\"eyebrow\">INSTAGRAM</span><p><a class=\"text-link\" href=\"https://www.instagram.com/docnovaltd\" target=\"_blank\" rel=\"noopener\">@docnovaltd</a></p></div><div><span class=\"eyebrow\">FACEBOOK</span><p><a class=\"text-link\" href=\"https://www.facebook.com/profile.php?id=61590798480298\" target=\"_blank\" rel=\"noopener\">DocNova on Facebook</a></p></div></div><p>For an existing order, please include your order number (it starts with DN-). You can also <a class=\"text-link\" href=\"#/track-order\">track your order</a> online.</p>"]};const t=texts[route.slice(1)];html=t?`<div class="content policy"><h1>${t[0]}</h1>${t[1]}${route==='/privacy'?'<button class="btn" onclick="clearData()">Clear my saved bag and wishlist</button>':'<p style="margin-top:28px"><a class="text-link" href="#/faq">Read our FAQs ↗</a></p>'}</div>`:'<div class="content"><h1>Let’s get you back.</h1><a class="btn" href="#/">Return home</a></div>'}$('#app').innerHTML=html;if(route==='/shop')filterProducts();if(route==='/order-confirmed'||route==='/confirmation')loadConfirmedOrder();if(route==='/rounds')initRounds();loadGoogleReviews();if(route==='/track-order'&&hashParam('order')&&hashParam('email'))trackOrder();document.title='DocNova — '+(route==='/'?'Premium Scrubs & Medical Essentials':route==='/rounds'?'DocNova Rounds — Loyalty & Referrals':route.startsWith('/product/')?selectedProduct?.name||'Collection':route.slice(1).replaceAll('-',' '));window.scrollTo(0,0);persist()}
function clearData(){cart=[];wishlist=[];appliedCoupon='';couponPercent=0;couponReward=false;['docnova-cart','docnova-wishlist','docnova-newsletter','docnova-coupon','docnova-welcome-subscribed'].forEach(k=>localStorage.removeItem(k));sessionStorage.removeItem('docnova-order');sessionStorage.removeItem('docnova-welcome-seen');persist();toast('Saved bag and wishlist cleared')}
window.addEventListener('hashchange',route);route();
// Optional browser agent tools share the same catalogue and cart actions as the UI.
if(document.modelContext?.registerTool){for(const tool of [{name:'search_docnova_products',description:'Read matching products in the local DocNova catalogue.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({query})=>{if(typeof query!=='string')throw Error('query must be a string');return products.filter(p=>(p.name+' '+p.color+' '+p.category).toLowerCase().includes(query.toLowerCase())).map(({id,name,price,color})=>({id,name,price,color}))}},{name:'add_docnova_item_to_bag',description:'Add one product and size to the local shopping bag. Does not place an order.',inputSchema:{type:'object',properties:{id:{type:'string'},size:{type:'string',enum:[...sizes,'Standard']}},required:['id','size'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({id,size})=>{const result=addToCart(id,size);openCart();return result}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}



if(removedUnavailableSizes)toast('Your bag was updated: only S, M, L and XL are available.');

function deviceQuickView(p){selectedSize='Standard';modal(`<img src="${imageOf(p)}" style="width:150px;height:190px;object-fit:contain;float:left;margin:0 25px 20px 0" alt="${p.name}"><span class="eyebrow">MEDICAL ESSENTIALS</span><h2>${p.name}</h2><p>${money(p.price)}</p><div style="clear:both"><button class="btn full" onclick="addSelected()">Add to bag — ${money(p.price)}</button><p><a class="text-link" href="#/product/${p.id}" onclick="closeModal()">View full details ↗</a></p></div>`)}
function devicePage(p){return `<div class="pdp"><div><p class="fine"><a href="#/shop?category=Medical%20Devices">Medical devices</a> / ${p.name}</p><img id="main-photo" class="gallery-main device-photo" src="${imageOf(p)}" alt="${p.name}" tabindex="0" role="button" onclick="zoomPhoto()" onkeydown="if(event.key==='Enter')zoomPhoto()"><div class="thumbs">${photos[p.group].map((im,i)=>`<button aria-label="View photograph ${i+1}" onclick="document.querySelector('#main-photo').src='${im}'"><img src="${im}" alt="${p.name}, view ${i+1}"></button>`).join('')}</div></div><div class="product-detail"><span class="eyebrow">MEDICAL ESSENTIALS</span><h1>${p.name}</h1><p class="price">${money(p.price)}</p>${(()=>{const d=deviceInfo[p.id];return d?`<p style="margin-top:18px">${d.intro}</p><ul class="device-points">${d.bullets.map(b=>`<li>${b}</li>`).join('')}</ul>`:''})()}<div class="mobile-add"><button class="btn" onclick="addSelected()">Add to bag — ${money(p.price)}</button><button class="btn outline" onclick="addSelected(true)">Buy now</button></div>${(()=>{const d=deviceInfo[p.id];return d?`<details open><summary>Specifications</summary><table class="spec-table">${d.specs.map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</table></details><details><summary>What’s in the box</summary><ul class="device-points">${d.box.map(b=>`<li>${b}</li>`).join('')}</ul></details><details><summary>Using your device safely</summary><p>For home use. Read the user manual before first use. Readings are for information and don’t replace advice from a healthcare professional — speak to your GP or pharmacist about your results, and call 999 or 111 in an emergency.</p></details>`:''})()}<details><summary>Delivery & returns</summary><p>UK delivery is £4.95, or free on orders of £70 or more (3–5 working days). Delivery to the Republic of Ireland is £9.95 (5–8 working days). Or choose free Click & Collect and our team will contact you the same day to arrange collection in the Cambridge area. You’ll get an order number straight away and a tracking number once your order is on its way.</p><p>Devices can be returned within 30 days if unopened and in their original sealed packaging. <a class="text-link" href="#/shipping">Delivery & returns ↗</a></p></details></div></div><section class="section"><h2>More medical essentials.</h2><div class="grid">${products.filter(x=>x.device&&x.id!==p.id).map(card).join('')}</div></section>`}

function colourOptions(p,quick=false){const variants=products.filter(x=>!x.device&&x.category===p.category&&x.fit===p.fit);return `<div class="colour-picker"><p>Colour — <strong>${p.color}</strong></p><div class="colour-options" aria-label="Available colours">${variants.map(v=>quick?`<button class="colour-option ${v.id===p.id?'active':''}" aria-pressed="${v.id===p.id}" onclick="quickView('${v.id}')"><span style="background:${colors[v.color]}"></span>${v.color}</button>`:`<a class="colour-option ${v.id===p.id?'active':''}" aria-current="${v.id===p.id?'true':'false'}" href="#/product/${v.id}"><span style="background:${colors[v.color]}"></span>${v.color}</a>`).join('')}</div></div>`}
function matchingPiece(p){if(!['Tops','Pants'].includes(p.category))return '';const match=products.find(x=>x.fit===p.fit&&x.color===p.color&&x.category===(p.category==='Tops'?'Pants':'Tops'));if(!match)return '';return `<aside class="matching-piece" aria-label="Complete the set"><span class="eyebrow">COMPLETE THE SET</span><p>Pair it with the matching ${p.category==='Tops'?'trousers':'top'} in ${p.color}.</p><div class="matching-product"><a href="#/product/${match.id}" onclick="closeModal()"><img src="${imageOf(match)}" alt="${match.name}"></a><div><a class="matching-title" href="#/product/${match.id}" onclick="closeModal()">${match.name}</a><p>${match.fit} · ${money(match.price)}</p><button class="text-link" onclick="quickView('${match.id}')">Choose size & add ↗</button></div></div><small>Top + trousers: ${money(p.price+match.price)}. Choose each size separately.</small></aside>`}

function rewardSetPrice(){return Math.max(0,...cart.map(x=>products.find(p=>p.id===x.id)).filter(p=>p&&p.category==='Sets').map(p=>p.price))}
function discountAmount(){return !appliedCoupon?0:couponReward?rewardSetPrice():Math.round(subtotal()*couponPercent)/100}
function orderTotal(){return Math.round((subtotal()-discountAmount()+deliveryCost())*100)/100}
function couponMarkup(){return `<form class="coupon-form" onsubmit="applyCoupon(event)"><label for="discount-code">Discount code</label><div><input id="discount-code" name="coupon" autocomplete="off" placeholder="Enter code" value="${appliedCoupon}"><button type="submit">Apply</button></div></form><p id="coupon-message" role="status" class="fine">${appliedCoupon?(couponReward?(rewardSetPrice()?'DocNova Rounds reward applied — one scrub set is on us.':'Add a scrub set to your bag to use your free-set reward.'):esc(appliedCoupon)+' applied — '+couponPercent+'% off your items. One code per order.'):''}</p>${appliedCoupon?`<p class="discount-line">${couponReward?'Rounds reward · free set':esc(appliedCoupon)+' · '+couponPercent+'% off'} <strong>−${money(discountAmount())}</strong> <button type="button" onclick="removeCoupon()" aria-label="Remove discount">×</button></p>`:''}`}
async function applyCoupon(e){e.preventDefault();const code=e.target.coupon.value.trim().toUpperCase(),msg=$('#coupon-message');if(!code)return;if(code===appliedCoupon){msg.textContent=code+' is already applied.';return}
 msg.textContent='Checking your code…';try{const res=await fetch('/api/coupon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code})});const d=await res.json().catch(()=>({}));if(!res.ok)throw Error(d.message||'That code is not recognised. Please check it and try again.');
 const replaced=appliedCoupon;appliedCoupon=d.code;couponPercent=d.percent_off||0;couponReward=!!d.reward;try{localStorage.setItem('docnova-coupon',JSON.stringify(d))}catch(_){}refreshCoupon();if(replaced)$('#coupon-message').textContent=`${d.reward?'Your free-set reward':d.code+' ('+d.percent_off+'% off)'} is applied. Only one code can be used per order, so it replaces ${replaced}.`}
 catch(err){msg.textContent=err.message.includes('fetch')?'We couldn’t check that code just now. Please try again.':err.message}}
function removeCoupon(){appliedCoupon='';couponPercent=0;couponReward=false;localStorage.removeItem('docnova-coupon');refreshCoupon()}
function refreshCoupon(){if($('#checkout-offer')){$('#checkout-offer').innerHTML=couponMarkup();const f=document.querySelector('.delivery-choices');if(f)f.outerHTML=deliveryChoices();if($('#delivery-line'))$('#delivery-line').innerHTML=deliveryLine();$('#order-total').textContent=money(orderTotal());if($('#checkout-rounds'))$('#checkout-rounds').innerHTML=roundsCartLine()}}
function welcomePopup(prefill=''){sessionStorage.setItem('docnova-welcome-seen','1');modal(`<div class="welcome-layout"><img class="welcome-image" src="assets/2-1.webp" alt="DocNova Pink premium scrubs"><div class="welcome-copy"><span class="eyebrow">WELCOME TO DOCNOVA</span><h2>Your essentials.<br>A little welcome gift.</h2><p class="welcome-discount">Enjoy <strong>10% off</strong> your first order</p><p>Join the DocNova list for new arrivals and members-first offers. We’ll email your personal welcome code straight to your inbox.</p><form id="welcome-form" onsubmit="subscribeWelcome(event)"><label for="welcome-email">Email address</label><input id="welcome-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="254"><label class="welcome-consent"><input type="checkbox" name="consent" required> <span>I’d like to receive DocNova emails and my welcome discount. I can unsubscribe at any time.</span></label><button class="btn full" type="submit">Subscribe & email my code</button><p id="welcome-status" role="status" aria-live="polite"></p></form><p class="fine">10% off products on your first order, excluding delivery. One code per order. <a href="#/privacy" onclick="closeModal()">Privacy notice</a></p><button class="text-link" onclick="closeModal()">Continue browsing</button></div></div>`);$('#modal').classList.add('welcome-dialog');$('#welcome-email').value=prefill}
async function subscribeWelcome(e){e.preventDefault();const form=e.target;const status=$('#welcome-status');const button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='Saving your subscription…';try{const response=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.email.value.trim(),consent:form.consent.checked})});const result=await response.json();if(!response.ok)throw new Error(result.message||'We couldn’t complete your signup. Please try again.');localStorage.setItem('docnova-welcome-subscribed','1');status.textContent=result.status==='sent'?'Thank you — you’re subscribed. Check your inbox for your 10% welcome code.':'Thank you — you’re on the list. Your 10% welcome code will arrive by email shortly.';button.textContent=result.status==='sent'?'Subscribed':'Subscribed';form.email.disabled=true;form.consent.disabled=true}catch(error){status.textContent='Sorry, we couldn’t sign you up just now. Please try again in a few minutes.';button.disabled=false}}
setTimeout(()=>{if(!sessionStorage.getItem('docnova-welcome-seen')&&!localStorage.getItem('docnova-welcome-subscribed')&&!$('#modal').open&&!location.hash.startsWith('#/checkout'))welcomePopup()},1400);

// ---- Stripe checkout, order confirmation and order tracking
var payInfo=null; // var: the footer renders before this line runs
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pence(n){return money((n||0)/100)}
function hashParam(name){return new URLSearchParams(location.hash.split('?')[1]||'').get(name)||''}
function payMethodsMarkup(){const list=payInfo?.methods||[{label:'Visa · Mastercard · Amex'},{label:'Apple Pay'},{label:'Google Pay'},{label:'Link'}];return list.map(m=>`<span class="pay-chip">${esc(m.label)}</span>`).join('')}
fetch('/api/payment-methods').then(r=>r.ok?r.json():null).then(d=>{if(!d)return;payInfo=d;document.querySelectorAll('#pay-methods,#footer-pay').forEach(el=>el.innerHTML=payMethodsMarkup())}).catch(()=>{});
async function startCheckout(){const btn=$('#pay-button'),err=$('#checkout-error');err.hidden=true;btn.disabled=true;btn.textContent='Opening secure payment…';
 try{const res=await fetch('/api/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart.map(x=>({id:x.id,size:x.size,qty:x.qty})),coupon:appliedCoupon,delivery:deliveryMethod})});
  const data=await res.json().catch(()=>({}));if(res.ok&&data.url){sessionStorage.setItem('docnova-pending-order',data.order_number);location.href=data.url;return}
  throw Error(data.message||'We could not start secure checkout. Please try again.')}
 catch(e){err.textContent=e.message.includes('fetch')?'Checkout is unavailable right now. Please check your connection and try again.':e.message;err.hidden=false;btn.disabled=false;btn.textContent='Continue to secure payment ↗'}}
var ORDER_STEPS=[['placed','Order placed'],['paid','Payment confirmed'],['dispatched','Dispatched'],['delivered','Delivered']];
function orderSteps(o){const reached={placed:1,paid:['paid','dispatched','delivered'].includes(o.status),dispatched:['dispatched','delivered'].includes(o.status),delivered:o.status==='delivered'};
 const when={placed:o.created_at,paid:o.paid_at,dispatched:o.dispatched_at,delivered:o.delivered_at};
 const steps=o.delivery_method==='collect'?[['placed','Order placed'],['paid','Payment confirmed'],['dispatched','Ready to collect'],['delivered','Collected']]:ORDER_STEPS;
 return `<ol class="order-steps">${steps.map(([k,l])=>`<li class="${reached[k]?'done':''}"><span></span><b>${l}</b>${reached[k]&&when[k]?`<small>${new Date(when[k]*1000).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}</small>`:''}</li>`).join('')}</ol>`}
function orderCard(o){const alert={payment_failed:'Your payment did not go through, so this order will not be sent. Please place a new order.',expired:'This checkout was not completed and no payment was taken.',processing:'Your payment is being confirmed by your bank. This can take up to a few working days; we’ll dispatch as soon as it clears.',cancelled:'This order has been cancelled.',refunded:'This order has been refunded.',partially_refunded:'Part of this order has been refunded.'}[o.status];
 return `<div class="order-card"><div class="order-head"><div><span class="eyebrow">ORDER NUMBER</span><strong class="order-number">${esc(o.order_number)}</strong></div><span class="order-status status-${esc(o.status)}">${esc(o.status_label)}</span></div>
 ${alert?`<div class="notice">${alert}</div>`:orderSteps(o)}
 ${o.tracking_number?`<div class="tracking-box"><span class="eyebrow">TRACKING</span><p><b>${esc(o.carrier||'Carrier')}</b> · ${esc(o.tracking_number)}</p>${o.tracking_url?`<a class="btn" href="${esc(o.tracking_url)}" target="_blank" rel="noopener">Track with ${esc(o.carrier||'carrier')} ↗</a>`:''}</div>`:''}
 <div class="order-lines">${o.items.map(i=>`<div><span>${i.qty} × ${esc(i.name)}${i.size==='Standard'?'':' · '+esc(i.size)}</span><span>${pence(i.unit_pence*i.qty)}</span></div>`).join('')}
 ${o.discount?`<div><span>Discount${o.coupon?' ('+esc(o.coupon)+')':''}</span><span>−${pence(o.discount)}</span></div>`:''}<div><span>${esc(o.delivery_label||'Delivery')}</span><span>${o.shipping?pence(o.shipping):'Free'}</span></div><div class="cart-total"><strong>Total</strong><strong>${pence(o.total)}</strong></div></div>
 ${o.delivery_method==='collect'?`<div class="notice collect-note"><b>Click & Collect.</b> The DocNova team will contact you on the day you order to arrange a collection time and place in the Cambridge area.</div>`:o.ship_to?`<p class="fine">Delivering to ${esc(o.name||'')}${o.name?', ':''}${esc(o.ship_to)}</p>`:''}</div>`}
function orderConfirmedPage(){return `<div class="content order-page" id="order-confirmed"><span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>Confirming your order…</h1><p>Just a moment while we confirm your payment with Stripe.</p></div>`}
async function loadConfirmedOrder(attempt=0){const sid=hashParam('session_id'),box=$('#order-confirmed');if(!box)return;
 if(!sid){box.innerHTML=`<span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>Looking for an order?</h1><p>Use your order number and email to see its status.</p><a class="btn" href="#/track-order">Track your order</a>`;return}
 try{const res=await fetch('/api/order?session_id='+encodeURIComponent(sid));const o=await res.json();if(!res.ok)throw Error(o.message);
  if(['paid','processing','dispatched','delivered'].includes(o.status)){cart=[];appliedCoupon='';try{localStorage.removeItem('docnova-coupon');sessionStorage.removeItem('docnova-pending-order')}catch(e){};persist()}
  if(o.status==='awaiting_payment'&&attempt<6){setTimeout(()=>loadConfirmedOrder(attempt+1),2000);return}
  const ok=['paid','dispatched','delivered'].includes(o.status);
  box.innerHTML=`<span class="eyebrow">${ok?'THANK YOU':'YOUR DOCNOVA ORDER'}</span><h1>${ok?'Your order is confirmed.':o.status==='processing'?'Your order is placed.':'Almost there.'}</h1><p>${ok||o.status==='processing'?'Keep your order number: you’ll need it, with your email, to track your order. Stripe will also email you a receipt.':'We’re still waiting for confirmation from Stripe. Refresh this page in a minute, or track your order with the number below.'}</p>${orderCard(o)}<div class="hero-actions"><a class="btn" href="#/track-order?order=${encodeURIComponent(o.order_number)}">Track this order</a><a class="text-link" href="#/shop">Continue shopping ↗</a></div>`}
 catch(e){box.innerHTML=`<span class="eyebrow">YOUR DOCNOVA ORDER</span><h1>We couldn’t load this order.</h1><p>${esc(e.message||'Please try again in a moment.')} If you were charged, your order is safe: track it with the order number from your receipt.</p><a class="btn" href="#/track-order">Track your order</a>`}}
function trackOrderPage(){return `<div class="content order-page"><span class="eyebrow">HERE TO HELP</span><h1>Track your order.</h1><p>Enter your order number (it starts with DN-) and the email address you used at checkout.</p>
 <form class="track-form" onsubmit="event.preventDefault();trackOrder()"><label>Order number<input id="track-number" name="order" required placeholder="DN-260926-7K4QP" autocomplete="off" value="${esc(hashParam('order'))}" pattern="\\s*[Dd][Nn]-\\d{6}-[A-Za-z0-9]{5}\\s*" title="For example DN-260926-7K4QP"></label><label>Email address<input id="track-email" type="email" required autocomplete="email" value="${esc(hashParam('email'))}"></label><button class="btn" id="track-button">Find my order</button></form><div id="track-result" role="status"></div></div>`}
async function trackOrder(){const out=$('#track-result'),btn=$('#track-button');btn.disabled=true;out.innerHTML='<p class="fine">Looking up your order…</p>';
 try{const res=await fetch('/api/track',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_number:$('#track-number').value.trim(),email:$('#track-email').value.trim()})});const o=await res.json().catch(()=>({}));
  out.innerHTML=res.ok?orderCard(o):`<div class="notice">${esc(o.message||'We couldn’t look up that order right now.')}</div>`}
 catch(e){out.innerHTML='<div class="notice">Order tracking is unavailable right now. Please try again shortly.</div>'}btn.disabled=false}

// ---- Live Google reviews (served by /api/reviews from Google's Places API; refreshed hourly on the server)
var reviewsRequest=null;
function starsMarkup(r,label){const pct=Math.max(0,Math.min(100,(Number(r)||0)/5*100));return `<span class="stars" style="--pct:${pct}%" role="img" aria-label="${label||('Rated '+(Number(r)||0).toFixed(1)+' out of 5')}"></span>`}
function reviewCard(r,i){const initial=esc((r.author||'G').trim().charAt(0).toUpperCase());const long=(r.text||'').length>260;
 return `<article class="gr-card"><div class="gr-head"><span class="gr-avatar">${r.photo?`<img src="${esc(r.photo)}" alt="" referrerpolicy="no-referrer" loading="lazy" onerror="this.remove()">`:''}<b>${initial}</b></span><div><h3>${r.author_url?`<a href="${esc(r.author_url)}" target="_blank" rel="noopener">${esc(r.author)}</a>`:esc(r.author)}</h3><small>${esc(r.when||'')}</small></div></div>${starsMarkup(r.rating)}
 ${r.text?`<p class="gr-text${long?' clamp':''}" id="gr-text-${i}">${esc(r.text)}</p>${long?`<button class="gr-more" aria-expanded="false" aria-controls="gr-text-${i}" onclick="const t=document.getElementById('gr-text-${i}');const o=t.classList.toggle('clamp');this.setAttribute('aria-expanded',!o);this.textContent=o?'Read more':'Show less'">Read more</button>`:''}`:'<p class="gr-text fine">Rated without a written review.</p>'}
 <div class="gr-foot"><span class="gr-g" aria-hidden="true">G</span><span>Posted on Google Maps</span>${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">View ↗</a>`:''}</div></article>`}
function reviewsSummary(rating,count,links,mapsUrl,note){const n=count||0;
 return `<span class="eyebrow">GOOGLE REVIEWS</span><h2>Worn on shift.<br><em>Rated on Google.</em></h2><div class="gr-score"><span class="gr-num">${(Number(rating)||0).toFixed(1)}</span><div>${starsMarkup(rating,'Average rating '+(Number(rating)||0).toFixed(1)+' out of 5')}<small>Based on ${n} Google review${n===1?'':'s'}</small></div></div><div class="gr-actions"><a class="btn outline" href="${esc(mapsUrl||links.maps)}" target="_blank" rel="noopener">Read all reviews on Google ↗</a><a class="text-link" href="${esc(links.write)}" target="_blank" rel="noopener">Write a review</a></div><p class="fine gr-note">${note}</p>`}
function reviewsMarkup(d){const links=d.links||{};
 if(d.live&&d.reviews&&d.reviews.length){
  // Highest-rated first, then newest; four fit the layout. The note below says so, as Google's policy asks.
  const top=[...d.reviews].sort((a,b)=>(b.rating||0)-(a.rating||0)||String(b.published||'').localeCompare(String(a.published||''))).slice(0,4);
  return {summary:reviewsSummary(d.rating,d.count,links,d.maps_url,'Live from Google Maps, updated hourly. Showing our highest-rated recent reviews, unedited. The rating above includes every review.'),
   list:top.map((r,i)=>reviewCard({...r,url:r.url||d.maps_url||links.maps},i)).join(''),n:top.length}}
 const f=d.featured;
 if(f&&f.reviews&&f.reviews.length){
  return {summary:reviewsSummary(f.rating,f.count,links,null,'Selected reviews from our Google profile, shown word for word. The rating above includes every review.'),
   list:f.reviews.slice(0,4).map((r,i)=>reviewCard({...r,url:links.maps},i)).join(''),n:Math.min(4,f.reviews.length)}}
 return {summary:`<span class="eyebrow">GOOGLE REVIEWS</span><h2>Worn on shift.<br><em>Rated on Google.</em></h2><p>Read what healthcare professionals say about DocNova scrubs and medical essentials on Google.</p><div class="gr-actions"><a class="btn" href="${esc(links.maps)}" target="_blank" rel="noopener">Read our Google reviews ↗</a><a class="text-link" href="${esc(links.write)}" target="_blank" rel="noopener">Write a review</a></div>`,list:'',n:0}}
function loadGoogleReviews(){const boxes=document.querySelectorAll('.g-reviews');if(!boxes.length)return;
 reviewsRequest=reviewsRequest||fetch('/api/reviews').then(r=>r.ok?r.json():Promise.reject()).catch(()=>({live:false,links:{maps:'https://www.google.com/maps/place/?q=place_id:ChIJsYc-YLZng2URQNsyBvUhTec',write:'https://search.google.com/local/writereview?placeid=ChIJsYc-YLZng2URQNsyBvUhTec'}}));
 reviewsRequest.then(d=>{const m=reviewsMarkup(d);boxes.forEach(b=>{b.querySelector('.gr-summary').innerHTML=m.summary;const l=b.querySelector('.gr-list');l.innerHTML=m.list;l.hidden=!m.list;l.dataset.count=m.n;b.classList.toggle('gr-live',!!m.list)})})}

(function(){if(document.getElementById('wa-float'))return;const a=document.createElement('a');a.id='wa-float';a.href='https://wa.me/353894484100?text=Hello%20DocNova';a.target='_blank';a.rel='noopener';a.setAttribute('aria-label','Chat with DocNova on WhatsApp');a.innerHTML='<svg viewBox="0 0 32 32" width="26" height="26" aria-hidden="true"><path fill="currentColor" d="M16 3a13 13 0 0 0-11.2 19.6L3 29l6.6-1.7A13 13 0 1 0 16 3zm0 23.7c-2 0-4-.5-5.7-1.6l-.4-.2-3.9 1 1-3.8-.3-.4A10.7 10.7 0 1 1 16 26.7zm5.9-8c-.3-.2-1.9-1-2.2-1s-.5-.2-.7.2-.8 1-1 1.2-.4.2-.7 0a8.8 8.8 0 0 1-4.4-3.8c-.3-.6.3-.5.9-1.7.1-.2 0-.4 0-.6l-1-2.4c-.3-.6-.5-.5-.7-.5h-.6a1.2 1.2 0 0 0-.9.4 3.7 3.7 0 0 0-1.1 2.7 6.4 6.4 0 0 0 1.3 3.4 14.7 14.7 0 0 0 5.7 5c2.1.9 2.9 1 4 .8.6-.1 1.9-.8 2.2-1.5s.3-1.4.2-1.5-.3-.2-.6-.3z"/></svg><span>WhatsApp</span>';document.body.appendChild(a)})();

/* ───────────── DocNova Rounds ───────────── */
function roundsEarn(c){return c==='Sets'?1:c==='Tops'||c==='Pants'?.5:0}
function roundsFmt(n){n=Math.round(n*2)/2;const w=Math.floor(n);return n%1?(w?w+'½':'½'):String(w)}
function roundsWord(n){return roundsFmt(n)+(n>0&&n<=1?' round':' rounds')}
function cartRounds(){let r=0;cart.forEach(x=>{const p=products.find(p=>p.id===x.id);if(p)r+=roundsEarn(p.category)*x.qty});if(typeof couponReward!=='undefined'&&couponReward)r-=1;return Math.max(0,r)}
function roundsCartLine(){const r=cartRounds();return r?`<p class="rounds-line"><span class="rounds-dot" aria-hidden="true"></span><span>This order earns <strong>${roundsWord(r)}</strong> with <a href="#/rounds" onclick="closeModal()">DocNova Rounds</a>.</span></p>`:''}
function productRoundsLine(p){const r=roundsEarn(p.category);return r?`<p class="rounds-line"><span class="rounds-dot" aria-hidden="true"></span><span>Earn <strong>${roundsWord(r)}</strong> with <a href="#/rounds">DocNova Rounds</a> — 10 rounds = a free scrub set.</span></p>`:''}
function stampCard(filled,opts={}){const f=Math.max(0,Math.min(10,filled));let h='';for(let i=1;i<=10;i++){const full=f>=i,half=!full&&f>=i-.5;h+=`<span class="stamp${full?' on':''}${half?' half':''}${i===10?' gift':''}" style="--i:${i}"><b>${i===10?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 11h16v10H4zM2.5 7.5h19V11h-19zM12 7.5V21M12 7.5C10.5 4 7 3.5 7 5.5S10 7.5 12 7.5zM12 7.5c1.5-3.5 5-4 5-2s-3 2-5 2z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg>':i}</b></span>`}
 return `<div class="stamp-card${opts.dark?' dark':''}" role="img" aria-label="${roundsFmt(f)} of 10 rounds"><div class="stamp-head"><img src="assets/docnova-logo-white.png" alt=""><span>ROUNDS CARD</span></div><div class="stamps">${h}</div><div class="stamp-foot"><span>${opts.label||roundsFmt(f)+' of 10 rounds'}</span><span>10 = a free set</span></div></div>`}
function roundsIcon(n){const p={join:'<path d="M12 21s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.6-7 10-7 10z"/>',bag:'<path d="M5 8h14l-1 13H6zM9 8V6a3 3 0 0 1 6 0v2"/>',gift:'<path d="M4 11h16v10H4zM2.5 7.5h19V11h-19zM12 7.5V21M12 7.5C10.5 4 7 3.5 7 5.5S10 7.5 12 7.5zM12 7.5c1.5-3.5 5-4 5-2s-3 2-5 2z"/>',share:'<circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="6" r="2.5"/><circle cx="18" cy="18" r="2.5"/><path d="m8.2 10.8 7.6-3.6M8.2 13.2l7.6 3.6"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-1.5a7 7 0 0 1 14 0V21"/>',star:'<path d="m12 3 2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1-4.4-4.3 6.1-.9z"/>',team:'<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2.5"/><path d="M2.5 20v-1a5.5 5.5 0 0 1 11 0v1M14 20v-1a4.5 4.5 0 0 1 7.5-3.4"/>',chat:'<path d="M4 5h16v11H9l-5 4z"/>'}[n];return `<svg viewBox="0 0 24 24" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">${p}</g></svg>`}

