var roundsSimState={sets:0,pieces:0,refs:0};
function roundsScroll(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}
function roundsSim(k,d){roundsSimState[k]=Math.max(0,Math.min(20,roundsSimState[k]+d));roundsSimRender()}
function roundsPreset(s,p,r){roundsSimState={sets:s,pieces:p,refs:r};roundsSimRender()}
function roundsSimRender(){const s=roundsSimState;['sets','pieces','refs'].forEach(k=>{const el=document.getElementById('sim-'+k);if(el)el.textContent=s[k]});const total=1+s.sets+s.pieces*.5+s.refs;const free=Math.floor(total/10),left=total-free*10;const card=document.getElementById('sim-card');if(card)card.innerHTML=stampCard(free&&!left?10:left,{label:free?`${free} free set${free>1?'s':''} earned · ${roundsFmt(left)} on your next card`:undefined});const out=document.getElementById('sim-result');if(out)out.innerHTML=free?`That’s <strong>${roundsWord(total)}</strong> — <strong>${free} free scrub set${free>1?'s':''}</strong>${left?`, with ${roundsWord(left)} already on your next card`:''}.`:`That’s <strong>${roundsWord(total)}</strong> — just <strong>${roundsWord(10-total)}</strong> from a free set.`}

async function roundsPost(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||'Something went wrong. Please try again.');return d}
async function roundsJoin(e){e.preventDefault();const st=$('#rj-status'),btn=$('#rj-btn'),email=$('#rj-email').value.trim();st.className='r-status';
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){st.classList.add('err');st.textContent='Please enter a valid email address.';return}
 if(!$('#rj-consent').checked){st.classList.add('err');st.textContent='Please tick the box to agree to the DocNova Rounds terms.';return}
 btn.disabled=true;btn.textContent='Joining…';
 try{const d=await roundsPost('/api/rounds/join',{email,consent:true,referrer:$('#rj-referrer')?.value.trim()||'',ref:$('#rj-ref')?.value||''});
  $('#rounds-join').innerHTML=`<div class="r-done">${roundsIcon('gift')}<h3>You’re in. Welcome to DocNova Rounds.</h3><p>${d.email_enabled?`We’ve emailed a private link to your card to <strong>${esc(email)}</strong>. If it isn’t there in a few minutes, check your junk folder.`:`Your card is ready. We’ll email your card link to <strong>${esc(email)}</strong> shortly.`}</p><p class="fine">Shop with this email address and your rounds are added automatically.</p><a class="btn" href="#/shop">Start earning — shop scrubs ↗</a></div>`}
 catch(err){st.classList.add('err');st.textContent=err.message;btn.disabled=false;btn.textContent='Join and claim my first round ↗'}}
async function roundsLink(e){e.preventDefault();const st=$('#rl-status'),email=$('#rl-email').value.trim();st.className='r-status';
 try{await roundsPost('/api/rounds/link',{email});st.classList.add('ok');st.textContent='If '+email+' is a DocNova Rounds member, a link to your card is on its way. Please check your inbox.'}
 catch(err){st.classList.add('err');st.textContent=err.message}}

function roundsReason(h){return {join:'Welcome bonus',referral:'Colleague referral',order:'Order',reward:'Free set reward',refund:'Refund',adjust:'Adjustment'}[h.reason]||h.reason}
function roundsDate(ts){return ts?new Date(ts*1000).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):''}
function roundsCopy(text,btn){const done=()=>{const t=btn.textContent;btn.textContent='Copied ✓';setTimeout(()=>btn.textContent=t,1800)};if(navigator.clipboard)navigator.clipboard.writeText(text).then(done,()=>prompt('Copy this:',text));else prompt('Copy this:',text)}
function roundsMember(d){const r=d.halves/2,goal=d.reward_at/2,left=Math.max(0,goal-r),link=location.origin+location.pathname+'#/rounds?ref='+d.ref_code;
 const msg=`I get my scrubs from DocNova — premium four-way-stretch scrubs made by healthcare professionals. Join DocNova Rounds with my link and earn towards a free scrub set: ${link}`;
 const open=(d.rewards||[]).filter(w=>!w.redeemed_order&&w.expires_at*1000>Date.now());
 return `<section class="r-member"><div class="r-member-main"><span class="eyebrow">YOUR DOCNOVA ROUNDS CARD</span><h2>Welcome back, <em>${esc(d.email)}</em></h2><p>${open.length?'You have a free scrub set waiting — use your code below at checkout.':left?`You’re <strong>${roundsWord(left)}</strong> away from a free scrub set of your choice.`:'Your reward is on its way.'}</p>${stampCard(r)}
 ${open.map(w=>`<div class="r-reward"><div><span class="eyebrow">FREE SET CODE · VALID UNTIL ${roundsDate(w.expires_at).toUpperCase()}</span><strong>${esc(w.code)}</strong></div><button class="btn light" onclick="roundsCopy('${esc(w.code)}',this)">Copy code</button></div>`).join('')}
 ${open.length?'<p class="fine" style="color:#c4c9d0">Add any scrub set to your bag and enter this code at checkout. One code per order.</p>':''}</div>
 <div class="r-member-side"><div class="r-share"><h3>${roundsIcon('share')} Refer a colleague</h3><p>Earn 1 round for every colleague who joins with your link and places their first order.${d.referrals?` <strong>${d.referrals} colleague${d.referrals>1?'s have':' has'} joined through you.</strong>`:''}</p><div class="r-link"><input readonly value="${esc(link)}" aria-label="Your referral link" onfocus="this.select()"><button onclick="roundsCopy('${esc(link)}',this)">Copy</button></div><div class="r-share-btns"><a class="btn" href="https://wa.me/?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">Share on WhatsApp</a><a class="btn outline" href="mailto:?subject=${encodeURIComponent('Join me on DocNova Rounds')}&body=${encodeURIComponent(msg)}">Share by email</a></div><p class="fine">Or ask them to enter your email in “Who referred you?”</p></div>
 <div class="r-history"><h3>Recent activity</h3>${(d.history||[]).length?`<ul>${d.history.map(h=>`<li><span>${roundsReason(h)}${h.reason==='order'||h.reason==='refund'?' <small>'+esc(h.ref)+'</small>':''}<small>${roundsDate(h.created_at)}</small></span><strong class="${h.halves<0?'neg':''}">${h.halves>0?'+':'−'}${roundsFmt(Math.abs(h.halves)/2)}</strong></li>`).join('')}</ul>`:'<p class="fine">Your rounds will appear here.</p>'}</div></div></section>`}
async function initRounds(){const t=hashParam('t');roundsSimState={sets:0,pieces:0,refs:0};
 if(hashParam('ref')){setTimeout(()=>roundsScroll('r-join'),350)}
 if(!t)return;const box=$('#r-member');box.innerHTML='<section class="r-member loading"><p>Opening your card…</p></section>';
 try{const r=await fetch('/api/rounds/me?t='+encodeURIComponent(t));const d=await r.json();if(!r.ok)throw new Error(d.message);box.innerHTML=roundsMember(d);setTimeout(()=>box.scrollIntoView({behavior:'smooth'}),200)}
 catch(err){box.innerHTML=`<section class="r-member expired"><div><span class="eyebrow">YOUR CARD</span><h2>This link has expired.</h2><p>${esc(err.message||'Enter your email below and we’ll send a fresh one.')}</p><button class="btn light" onclick="roundsScroll('r-card')">Send me a new link ↗</button></div></section>`}}
